import json
import os
import shutil
import subprocess


def emit(results, harness_error=None):
    obj = {"results": results}
    if harness_error is not None:
        obj["harness_error"] = harness_error
    print(json.dumps(obj))


def main():
    try:
        with open("inputs.json", encoding="utf-8") as f:
            items = json.load(f)
    except Exception as e:
        emit([], "cannot read inputs.json: " + str(e))
        return

    ids = [it.get("id") for it in items]
    pre_errors = {}
    tsv = []
    try:
        shutil.copyfile("block-0.txt", "WordCounter.java")
        os.makedirs("cases", exist_ok=True)
        for k, it in enumerate(items):
            content = (it.get("input") or {}).get("content")
            if not isinstance(content, str):
                pre_errors[k] = "invalid input: content must be a string"
                continue
            path = os.path.abspath(os.path.join("cases", "case%d.txt" % k))
            with open(path, "w", encoding="utf-8", newline="") as f:
                f.write(content)
            tsv.append("%d%s%s" % (k, chr(9), path))
        with open("cases.tsv", "w", encoding="utf-8") as f:
            f.write("".join(line + chr(10) for line in tsv))
    except Exception as e:
        emit([], "setup failed: " + str(e))
        return

    try:
        comp = subprocess.run(["javac", "WordCounter.java", "Driver.java"],
                              capture_output=True, text=True, timeout=5)
    except Exception as e:
        emit([], "javac infrastructure failure: " + str(e))
        return

    compile_msg = None
    if comp.returncode != 0:
        compile_msg = "compile error: " + ((comp.stderr or "") + (comp.stdout or ""))[-2000:]

    by_k = {}
    if compile_msg is None:
        try:
            run = subprocess.run(["java", "-cp", ".", "Driver"],
                                 capture_output=True, text=True, timeout=5)
        except Exception as e:
            emit([], "java infrastructure failure: " + str(e))
            return
        if run.returncode != 0:
            emit([], "driver failed: " + (run.stderr or "")[-1000:])
            return
        try:
            with open("results.jsonl", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if line:
                        obj = json.loads(line)
                        by_k[int(obj["id"])] = obj
        except Exception as e:
            emit([], "cannot read driver results: " + str(e))
            return

    results = []
    for k, cid in enumerate(ids):
        if k in pre_errors:
            results.append({"id": cid, "error": pre_errors[k]})
        elif compile_msg is not None:
            results.append({"id": cid, "error": compile_msg})
        elif k in by_k:
            obj = by_k[k]
            if "error" in obj:
                results.append({"id": cid, "error": obj["error"]})
            else:
                results.append({"id": cid, "actual": obj["actual"]})
        else:
            results.append({"id": cid, "error": "no result produced for this case"})
    emit(results)


if __name__ == "__main__":
    main()

