import java.io.*;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;

public class Driver {

    static String esc(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append((char) 34);
        for (char c : s.toCharArray()) {
            if (c == 34 || c == 92) sb.append((char) 92).append(c);
            else if (c < 32) sb.append(' ');
            else sb.append(c);
        }
        sb.append((char) 34);
        return sb.toString();
    }

    static List<?> listField(String name) throws Exception {
        Field f = WordCounter.class.getDeclaredField(name);
        f.setAccessible(true);
        return (List<?>) f.get(null);
    }

    static String listJson(List<?> list) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) sb.append(',');
            Object o = list.get(i);
            sb.append(o == null ? "null" : esc(String.valueOf(o)));
        }
        return sb.append(']').toString();
    }

    public static void main(String[] args) throws Exception {
        PrintStream realOut = System.out;
        InputStream realIn = System.in;
        Pattern countLine = Pattern.compile("^([0-9]+) letters? -- ([0-9]+) words?$");
        List<String> lines = Files.readAllLines(Paths.get("cases.tsv"), StandardCharsets.UTF_8);
        try (PrintWriter pw = new PrintWriter(Files.newBufferedWriter(Paths.get("results.jsonl"), StandardCharsets.UTF_8))) {
            for (String line : lines) {
                if (line.isEmpty()) continue;
                int tab = line.indexOf((char) 9);
                String id = line.substring(0, tab);
                String path = line.substring(tab + 1);
                ByteArrayOutputStream buf = new ByteArrayOutputStream();
                PrintStream cap = new PrintStream(buf, true, "UTF-8");
                String entry;
                try {
                    listField("unmodifiedWords").clear();
                    listField("modifiedWords").clear();
                    System.setIn(new ByteArrayInputStream((path + (char) 10).getBytes(StandardCharsets.UTF_8)));
                    System.setOut(cap);
                    WordCounter.main(new String[0]);
                    cap.flush();
                    System.setOut(realOut);

                    Map<String, Long> counts = new LinkedHashMap<>();
                    for (String l : buf.toString("UTF-8").split(String.valueOf((char) 10))) {
                        Matcher m = countLine.matcher(l.trim());
                        if (m.matches()) counts.put(m.group(1), Long.parseLong(m.group(2)));
                    }
                    StringBuilder cj = new StringBuilder("{");
                    boolean first = true;
                    for (Map.Entry<String, Long> e : counts.entrySet()) {
                        if (!first) cj.append(',');
                        first = false;
                        cj.append(esc(e.getKey())).append(':').append(e.getValue());
                    }
                    cj.append('}');

                    List<?> un = listField("unmodifiedWords");
                    List<?> mo = listField("modifiedWords");
                    entry = "{" + esc("id") + ":" + esc(id) + "," + esc("actual") + ":{"
                            + esc("unmodified") + ":" + listJson(un) + ","
                            + esc("modified") + ":" + listJson(mo) + ","
                            + esc("counts") + ":" + cj.toString() + "}}";
                } catch (Throwable t) {
                    entry = "{" + esc("id") + ":" + esc(id) + "," + esc("error") + ":" + esc(String.valueOf(t)) + "}";
                } finally {
                    System.setOut(realOut);
                    System.setIn(realIn);
                }
                pw.println(entry);
            }
        }
    }
}

