import json
import os
import re
import subprocess
import sys

LIST_TAG = "@@LIST@@"

def emit(results, herr=None):
    obj = {"results": results}
    if herr is not None:
        obj["harness_error"] = herr
    sys.stdout.write(json.dumps(obj, ensure_ascii=True) + "\n")

def parse_stdout(text):
    lists = []
    counts = {}
    for line in text.splitlines():
        if line.startswith(LIST_TAG):
            lists.append(json.loads(line[len(LIST_TAG):]))
        else:
            m = re.match(r"^(\d+) letters? -- (\d+) words?$", line.strip())
            if m and int(m.group(1)) > 0:
                counts[str(int(m.group(1)))] = int(m.group(2))
    if len(lists) != 2:
        raise ValueError("expected 2 word lists, got %d" % len(lists))
    return {"unmodified": lists[0], "modified": lists[1], "counts": counts}

def main():
    base = os.getcwd()
    work = os.path.join(base, "work")
    try:
        os.makedirs(work, exist_ok=True)
        with open(os.path.join(base, "inputs.json"), "r", encoding="utf-8") as f:
            cases = json.load(f)
        if not isinstance(cases, list):
            raise ValueError("inputs.json is not a list")
        with open(os.path.join(base, "block-0.txt"), "r", encoding="utf-8") as f:
            src = f.read()
        with open(os.path.join(base, "HarnessRunner.java"), "r", encoding="utf-8") as f:
            runner = f.read()
        with open(os.path.join(work, "WordCounter.java"), "w", encoding="utf-8", newline="") as f:
            f.write(src)
        with open(os.path.join(work, "HarnessRunner.java"), "w", encoding="utf-8", newline="") as f:
            f.write(runner)
    except Exception as e:
        emit([], "setup failed: %s: %s" % (type(e).__name__, e))
        return

    compile_err = None
    try:
        jc = subprocess.run(
            ["javac", "-encoding", "UTF-8", "-d", work, "WordCounter.java", "HarnessRunner.java"],
            cwd=work, capture_output=True, encoding="utf-8", timeout=5)
        if jc.returncode != 0:
            compile_err = ((jc.stderr or "") + (jc.stdout or ""))[-1000:]
    except subprocess.TimeoutExpired:
        compile_err = "javac timed out"
    except OSError as e:
        emit([], "javac unavailable: %s" % e)
        return

    results = []
    for idx, case in enumerate(cases):
        cid = case.get("id") if isinstance(case, dict) else None
        if compile_err is not None:
            results.append({"id": cid, "error": "compile failed: " + compile_err})
            continue
        try:
            content = case["input"]["content"]
            if not isinstance(content, str):
                raise ValueError("content is not a string")
        except Exception as e:
            results.append({"id": cid, "error": "bad input: %s" % e})
            continue
        fpath = os.path.abspath(os.path.join(work, "case_%d.txt" % idx))
        with open(fpath, "w", encoding="utf-8", newline="") as f:
            f.write(content)
        try:
            p = subprocess.run(
                ["java", "-cp", work, "HarnessRunner"],
                input=fpath + "\n", capture_output=True, encoding="utf-8", timeout=5)
        except subprocess.TimeoutExpired:
            results.append({"id": cid, "error": "candidate timed out after 5 seconds"})
            continue
        except OSError as e:
            emit(results, "java unavailable: %s" % e)
            return
        if p.returncode != 0:
            err = (p.stderr or "").strip()
            results.append({"id": cid, "error": "candidate exited with code %d: %s" % (p.returncode, err[-500:])})
            continue
        try:
            actual = parse_stdout(p.stdout or "")
        except Exception as e:
            results.append({"id": cid, "error": "could not parse candidate output: %s" % e})
            continue
        results.append({"id": cid, "actual": actual})
    emit(results)

if __name__ == "__main__":
    main()

