import java.io.FileDescriptor;
import java.io.FileOutputStream;
import java.io.PrintStream;
import java.util.Collection;

public class HarnessRunner {
    public static void main(String[] args) throws Exception {
        PrintStream cap = new PrintStream(new FileOutputStream(FileDescriptor.out), true, "UTF-8") {
            @Override
            public void println(Object x) {
                if (x instanceof Collection) {
                    StringBuilder sb = new StringBuilder("@@LIST@@[");
                    boolean first = true;
                    for (Object o : (Collection<?>) x) {
                        if (!first) sb.append(',');
                        first = false;
                        sb.append('"');
                        for (char c : String.valueOf(o).toCharArray()) {
                            if (c == '\\' || c == '"') sb.append('\\');
                            sb.append(c);
                        }
                        sb.append('"');
                    }
                    sb.append(']');
                    super.println(sb.toString());
                } else {
                    super.println(x);
                }
            }
        };
        System.setOut(cap);
        WordCounter.main(new String[0]);
        cap.flush();
    }
}
